using System;using System.IO;using System.Reflection;using UnityEngine;
public static class NetworkRibbonAcceptance {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 public static object Main(){var a=typeof(EchoSphere.Runtime.EchoSphereRuntime).Assembly;var st=a.GetType("EchoSphere.Presentation.NativeWorldSurface");var nt=a.GetType("EchoSphere.Presentation.NativeWorldNetwork");var point=nt.GetNestedType("Node",F);object Call(object o,string n,params object[] args)=>o.GetType().GetMethod(n,F).Invoke(o,args);var go=new GameObject("Network ribbon acceptance");var s=go.AddComponent(st);Call(s,"Initialize");Call(s,"SetViewport",360f,240f,1.75f);var n=Activator.CreateInstance(nt,true);object Node(double x,double y){var p=Activator.CreateInstance(point);point.GetField("X",F).SetValue(p,x);point.GetField("Y",F).SetValue(p,y);return p;}var from=Node(-120,-50);var to=Node(120,50);Color32[] Read(){var rt=(RenderTexture)st.GetProperty("CompositeTexture",F).GetValue(s);var old=RenderTexture.active;RenderTexture.active=rt;var im=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false,true);im.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);im.Apply();RenderTexture.active=old;var px=im.GetPixels32();UnityEngine.Object.DestroyImmediate(im);return px;}double worst=0;try{for(int sample=0;sample<6;sample++){Color32[] before=null;for(int mode=0;mode<2;mode++){nt.GetField("UseVectorNetworkForValidation",F).SetValue(n,mode==0);Call(s,"Begin",Vector2.zero);Call(s,"ResetTransform");Call(n,"BeginFrame");Call(n,"DrawLink",s,from,to,Color.cyan,.5d,sample*.31d,0d,sample%2==0);Call(s,"End");var px=Read();if(mode==0)before=px;else{long sum=0;for(int i=0;i<px.Length;i++)sum+=Math.Abs(px[i].r-before[i].r)+Math.Abs(px[i].g-before[i].g)+Math.Abs(px[i].b-before[i].b);double mean=sum/(double)(px.Length*3);worst=Math.Max(worst,mean);if(mean>.3)throw new Exception("ribbon difference "+mean);}}}var cpu=new double[2];for(int mode=0;mode<2;mode++){nt.GetField("UseVectorNetworkForValidation",F).SetValue(n,mode==0);var watch=System.Diagnostics.Stopwatch.StartNew();for(int i=0;i<200;i++){Call(s,"Begin",Vector2.zero);Call(n,"BeginFrame");Call(n,"DrawLink",s,from,to,Color.cyan,.5d,i*.016d,0d,true);}watch.Stop();cpu[mode]=watch.Elapsed.TotalMilliseconds/200;}return new{result="PASS",samples=6,worstMeanRgb=worst,editorLinkCpuBeforeMs=cpu[0],editorLinkCpuAfterMs=cpu[1]};}finally{((IDisposable)n).Dispose();UnityEngine.Object.DestroyImmediate(go);}}
}
